/* amirsalmani/code — a block you are meant to copy.
 *
 * Requires tokens.css. No syntax highlighting: that needs colour, and there is
 * none to spend (brand.md §7). A copy control is the only affordance, and it
 * sits in the corner as mono uppercase so it reads as a key rather than a
 * button competing with the code.
 */

.as-code {
  position: relative;
  margin: 0;
  padding: 1rem 1.1rem;
  border: 1px solid var(--rule);
  border-radius: var(--radius-s);
  background: var(--wash);
  overflow-x: auto;
}
.as-code code {
  font-family: var(--mono);
  font-size: .85rem;
  line-height: 1.65;
  color: var(--fg);
  white-space: pre;
}
.as-code__copy {
  position: absolute;
  top: .5rem;
  right: .5rem;
  padding: .35rem .55rem;
  border: 1px solid var(--rule);
  border-radius: 6px;
  background: var(--bg);
  color: var(--muted);
  font-family: var(--mono);
  font-size: .62rem;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--fast) var(--ease-out), color var(--fast) var(--ease-out), border-color var(--fast) var(--ease-out);
}
.as-code:hover .as-code__copy,
.as-code__copy:focus-visible { opacity: 1; }
.as-code__copy:hover { color: var(--fg); border-color: var(--fg); }
.as-code__copy:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.as-code__copy[data-copied] { opacity: 1; color: var(--fg); border-color: var(--fg); }

/* A pointer is not guaranteed, so on touch the control is simply always there. */
@media (hover: none) { .as-code__copy { opacity: 1; } }

.as-code--inline, code.as-code-inline {
  font-family: var(--mono);
  font-size: .9em;
  padding: .1em .35em;
  border-radius: 4px;
  background: var(--wash);
  color: var(--fg);
}

@media (prefers-contrast: more) { .as-code { background: var(--bg); border-color: var(--fg); } }
